import {FileAdds} from '../../../models';
import {Component, Input} from '@angular/core';
import {DecimalPipe} from "@angular/common";
import {NzSpinModule} from "ng-zorro-antd/spin";
import {MarkdownRoot} from "../markdown-root/markdown-root";
import {ChatModel} from "../../../models";
import {NzImageDirective} from "ng-zorro-antd/image";
import {TranslateModule} from '@ngx-translate/core';
@Component({
  selector: 'app-chat',
  templateUrl: './chat.html',
  styleUrl: './chat.css',
  imports: [
    DecimalPipe,
    NzSpinModule,
    MarkdownRoot,
    NzImageDirective,
    TranslateModule
  ],
  standalone: true
})
export class Chat {
  @Input() chatModel?: ChatModel;

  get pending(): boolean {
    return !this.chatModel?.content && !this.chatModel?.fileList?.length;
  }

  readonly previewTypes = new Set(['image/png', 'image/jpeg', 'image/webp', 'image/gif']);

  imageSource(file: FileAdds): string | undefined {
    if (!file.fileContent || !file.fileType?.startsWith('image/')) return undefined;
    if (file.fileContent.startsWith('data:image/')) return file.fileContent;
    if (this.previewTypes.has(file.fileType)) return 'data:' + file.fileType + ';base64,' + file.fileContent;
    return undefined;
  }

  download(file: FileAdds): void {
    if (!file.fileContent) return;
    const encoded = file.fileContent.startsWith('data:')
      ? file.fileContent.slice(file.fileContent.indexOf(',') + 1) : file.fileContent;
    const bytes = Uint8Array.from(atob(encoded), character => character.charCodeAt(0));
    const url = URL.createObjectURL(new Blob([bytes], {type: 'application/octet-stream'}));
    const anchor = document.createElement('a');
    anchor.href = url;
    anchor.download = file.fileName;
    anchor.click();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  }

  fallback =
    'data:image/png;base64,';

  getIcon(type: string,fileName: string) {
    if(type.startsWith("audio")){
      return "assets/svgs/audio.svg";
    }
    if (type.startsWith("text")) {
      const fileExtension = fileName.split('.').pop(); // 获取文件后缀
      switch (fileExtension) {
        case 'cs':
          return 'assets/svgs/csharp.svg'; // C# 文件的 icon 地址
        case 'java':
          return 'assets/svgs/java.svg'; // Java 文件的 icon 地址
        case 'py':
          return 'assets/svgs/py.svg'; // Python 文件的 icon 地址
        case 'ts':
          return 'assets/svgs/ts.svg'; // TypeScript 文件的 icon 地址
        case 'txt':
        case 'text':
          return 'assets/svgs/plaintext.svg'; // 普通文本文件的 icon 地址
        default:
          return 'assets/svgs/code.svg'; // 其他文本文件的 icon 地址
      }
    }
    return "assets/svgs/file.svg";
  }
}
